mutation.before:
resources: list(
  z.strictObject({
    id,
    generation: count,
    holder: text,
    waiters: list(id),
    actions: list(resourceAction),
  }),
),

mutation.after:
resources: list(
  z.strictObject({
    id,
    generation: z.optional(count),
    holder: text,
    waiters: list(id),
    actions: list(resourceAction),
  }),
),
